10	    /// Extract default values from destructured function parameters.
11	    ///
12	    /// Handles `({ size = 'md', disabled = false }: Props) => ...` patterns.
13	    pub(super) fn extract_param_defaults<'a>(
14	        &self,
15	        params: &FormalParameters<'a>,
16	    ) -> rustc_hash::FxHashMap<String, RawDefault> {
17	        let mut defaults = rustc_hash::FxHashMap::default();
18	
19	        let Some(first_param) = params.items.first() else {
20	            return defaults;
21	        };
22	        // In OXC 0.135, BindingPattern is an enum directly (not a struct with .kind)
23	        let BindingPattern::ObjectPattern(obj) = &first_param.pattern else {
24	            return defaults;
25	        };
26	
27	        for prop in &obj.properties {
28	            // In OXC 0.135, BindingProperty.value is BindingPattern.
29	            // A default value `{ size = 'md' }` is represented as
30	            // BindingProperty { key: "size", value: BindingPattern::AssignmentPattern { left: "size", right: 'md' } }
31	            let (name, default_expr) = match &prop.value {
32	                BindingPattern::AssignmentPattern(ap) => {
33	                    let name = match &ap.left {
34	                        BindingPattern::BindingIdentifier(id) => id.name.as_str().to_owned(),
35	                        _ => continue,
36	                    };
37	                    (name, &ap.right)
38	                }
39	                _ => continue,
40	            };
41	            let raw_default = self.eval_expr_as_default(default_expr, DefaultSource::Destructuring);
42	            defaults.insert(name, raw_default);
43	        }
44	        defaults
45	    }
46	
47	    pub(super) fn eval_expr_as_default<'a>(&self, expr: &Expression<'a>, source: DefaultSource) -> RawDefault {
48	        match expr {
49	            Expression::StringLiteral(s) => {
50	                RawDefault { value: format!("\"{}\"", s.value.as_str()), computed: false, source }
51	            }
52	            Expression::NumericLiteral(n) => RawDefault { value: n.value.to_string(), computed: false, source },
53	            Expression::BooleanLiteral(b) => RawDefault { value: b.value.to_string(), computed: false, source },
54	            Expression::NullLiteral(_) => RawDefault { value: "null".into(), computed: false, source },
55	            Expression::Identifier(id) if id.name.as_str() == "undefined" => {
56	                RawDefault { value: "undefined".into(), computed: false, source }
57	            }
58	            // Array and object literals: capture source text, not computed
59	            Expression::ArrayExpression(_) | Expression::ObjectExpression(_) => {
60	                use oxc_span::GetSpan;
61	                let span = expr.span();
62	                RawDefault {
63	                    value: self.source[span.start as usize..span.end as usize].to_owned(),
64	                    computed: false,
65	                    source,
66	                }
67	            }
68	            // Everything else (identifier refs, calls, ternaries): computed
69	            _ => {
70	                use oxc_span::GetSpan;
71	                let span = expr.span();
72	                RawDefault {
73	                    value: self.source[span.start as usize..span.end as usize].to_owned(),
74	                    computed: true,
75	                    source,
76	                }
77	            }
78	        }
79	    }
80	}
