16	/// Canonicalize `path`, falling back to canonicalizing its parent directory
17	/// and rejoining the file name when the full path can't be resolved (e.g. the
18	/// file doesn't exist yet — created and then immediately edited before this
19	/// session ever saw it read successfully). Falls back to `path` unchanged only
20	/// when even the parent doesn't exist. Deliberately stable across a file's
21	/// create/delete transitions: the parent directory is what actually needs a
22	/// consistent identity across repeated `update_file` calls for the same file,
23	/// not the file itself.
24	fn canonicalize_best_effort(path: &Utf8Path) -> Utf8PathBuf {
25	    if let Ok(p) = std::fs::canonicalize(path.as_std_path()) {
26	        if let Ok(p) = Utf8PathBuf::from_path_buf(p) {
27	            return p;
28	        }
29	    }
30	    if let (Some(parent), Some(file_name)) = (path.parent(), path.file_name()) {
31	        if let Ok(p) = std::fs::canonicalize(parent.as_std_path()) {
32	            if let Ok(mut p) = Utf8PathBuf::from_path_buf(p) {
33	                p.push(file_name);
34	                return p;
35	            }
36	        }
37	    }
38	    path.to_owned()
39	}
